import{at as e,it as t,n,vt as r}from"./chunks/framework.B0lbOe_c.js";var i=JSON.parse(`{"title":"Deleted entities","description":"","frontmatter":{"title":"Deleted entities","covers":{"screens":["SCR-068"],"stories":["US-074"]}},"headers":[],"relativePath":"usage/deleted-entities.md","filePath":"usage/deleted-entities.md"}`),a={name:`usage/deleted-entities.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="deleted-entities" tabindex="-1">Deleted entities <a class="header-anchor" href="#deleted-entities" aria-label="Permalink to “Deleted entities”">​</a></h1><p>When you delete an entity from the repository (for example <em>Delete from repository</em> on the canvas of a <a href="./diagrams#the-canvas">diagram</a>), OEA does not remove it: the entity, its children and their connections are marked as deleted and can be restored. The page <em>Deleted entities</em> lists them. It needs the permission <code>entity:restore</code> (role <code>enterprise-architect</code>); without it the header has no entry <em>Deleted entities</em>, and the page shows <em>No permission</em>.</p><h2 id="find-deleted-entities" tabindex="-1">Find deleted entities <a class="header-anchor" href="#find-deleted-entities" aria-label="Permalink to “Find deleted entities”">​</a></h2><p>Choose <em>Deleted entities</em> in the header. The page lists the deleted entities and connections, the latest deletion first. Each entry shows:</p><ul><li>the name and, for a connection, its source and target (also when they are deleted themselves), the entity type, and the person and time of the deletion;</li><li><em>Deleted with …</em> and the name of an entity, if the entry was taken along when that entity was deleted, for example a child or a connection of it.</li></ul><p>Type a part of a name into <em>Filter by name</em> (up to 255 characters; characters such as <code>%</code> and <code>_</code> are matched as typed) and choose an entity type to narrow the list. The list shows 50 entries at a time; choose <em>Load more</em> for the next ones. Without any deleted entity the page says <em>No deleted entities.</em></p><h2 id="restore-an-entity" tabindex="-1">Restore an entity <a class="header-anchor" href="#restore-an-entity" aria-label="Permalink to “Restore an entity”">​</a></h2><ol><li>Choose <em>Restore</em> on an entry.</li><li>Confirm the dialog. The entity comes back together with what its deletion took along: its children and their connections that were deleted with it.</li></ol><p>Afterwards a notice names the entities that were restored and those that stayed deleted. A connection stays deleted if its other endpoint is still deleted; restore that entity as well, and then the connection. An element whose parent is still deleted comes back at the top level, and the notice says so.</p><ul><li><strong>A single entry:</strong> an entry that was taken along, for example a child, can be restored on its own. The dialog names the entity it was deleted with.</li><li><strong>A connection with a deleted endpoint:</strong> restoring it alone is refused. The page says so; restore the endpoint first.</li><li><strong>Someone was faster:</strong> if the entity was restored or changed meanwhile, the page says so and reloads the list.</li></ul><p>Restoring changes no version and is recorded in the audit trail as <code>entity.undeleted</code> for each restored entity.</p><h2 id="deleted-rows-in-a-catalog" tabindex="-1">Deleted rows in a catalog <a class="header-anchor" href="#deleted-rows-in-a-catalog" aria-label="Permalink to “Deleted rows in a catalog”">​</a></h2><p>A catalog can show deleted rows as well, with the switch <em>Show deleted</em> (see <a href="./catalogs#show-deleted">Catalogs</a>). <em>Restore</em> works there the same way.</p><h2 id="through-the-api" tabindex="-1">Through the API <a class="header-anchor" href="#through-the-api" aria-label="Permalink to “Through the API”">​</a></h2><ul><li><code>GET /entities/deleted</code> lists the deleted entities and connections (<code>entity:restore</code>): the latest deletion first, then by ID. <code>q</code> is a part of the name (at most 255 characters), <code>metatypeId</code> an entity type, <code>pageSize</code> is 1 to 200 (default 50) and <code>page</code> starts at 0. The answer carries <code>nextCursor</code>; send it as <code>cursor</code> together with <code>page</code> increased by 1 to continue. A cursor of another query is rejected with 400 naming <code>cursor</code>; other invalid values answer 400.</li><li>Each entry has <code>id</code>, <code>name</code>, <code>metatype</code>, <code>isConnection</code>, for a connection <code>source</code> and <code>target</code> (<code>id</code> and <code>name</code>), <code>version</code>, <code>deletedAt</code>, <code>deletedBy</code> and <code>deletedWith</code> (<code>id</code> and <code>name</code>, or <code>null</code> for an entity that was deleted on its own). It carries no property values.</li><li><code>POST /entities/{id}/undelete</code> with the header <code>If-Match</code> and the <code>version</code> of the entry restores the entity (see <a href="./diagrams#through-the-api">Diagrams</a>). The list is read only and not audited.</li></ul>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};